    fn show_file(
        &mut self,
        path: PathBuf,
        position: Option<lsp_types::Position>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.file.is_none() && self.diff.is_none() {
            // Fresh split sizes, so the file opens at its share of the width.
            self.file_split = cx.new(|_| ResizableState::default());
            self.pane_opened = Some((self.pane_opened.map_or(0, |(n, _)| n) + 1, Instant::now()));
        }
        self.diff = None;
        let file = cx.new(|cx| FileView::new(path, position, window, cx));
        self._file_subscriptions = vec![
            cx.subscribe(&file, |this, _, _: &CloseFile, cx| {
                this.file = None;
                cx.notify();
            }),
            cx.subscribe_in(
                &file,
                window,
                |this, _, definition: &OpenDefinition, window, cx| {
                    this.open_file_at(
                        definition.path.clone(),
                        Some(definition.position),
                        window,
                        cx,
                    )
                },
            ),
        ];
        self.file = Some(file);
        cx.notify();
    }

    /// Opens a changed file's diff beside the task view, in place of any file
    /// or diff open, first asking whether to discard any unsaved changes to
    /// the file it replaces.
    pub fn open_diff(&mut self, path: PathBuf, window: &mut Window, cx: &mut Context<Self>) {
        if let Some(file) = self.file.as_ref().filter(|file| file.read(cx).is_dirty()) {
            let title = file.read(cx).title();
            let this = cx.entity().downgrade();
            FileView::confirm_discard(title, window, cx, move |window, cx| {
                this.update(cx, |this, cx| this.show_diff(path.clone(), window, cx))
                    .ok();
            });
            return;
        }
        self.show_diff(path, window, cx);
    }

    fn show_diff(&mut self, path: PathBuf, window: &mut Window, cx: &mut Context<Self>) {
        if self.file.is_none() && self.diff.is_none() {
            self.file_split = cx.new(|_| ResizableState::default());
            self.pane_opened = Some((self.pane_opened.map_or(0, |(n, _)| n) + 1, Instant::now()));
        }
        self.file = None;
        let diff = cx.new(|cx| DiffView::new(path, cx));
        self._file_subscriptions = vec![
            cx.subscribe(&diff, |this, _, _: &CloseDiff, cx| {
                this.diff = None;
                cx.notify();
            }),
            cx.subscribe_in(&diff, window, |this, _, OpenInEditor(path), window, cx| {
                this.open_file(path.clone(), window, cx)
            }),
        ];
        diff.read(cx).focus_handle(cx).focus(window, cx);
        self.diff = Some(diff);
        cx.notify();
    }

